-- +goose Up
CREATE TABLE IF NOT EXISTS "organization" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "parent_id" BIGINT REFERENCES "organization"("id") ON DELETE RESTRICT,
  "name" VARCHAR(64) NOT NULL,
  "code" VARCHAR(64) NOT NULL,
  "manager" VARCHAR(64) NOT NULL DEFAULT '',
  "status" BOOLEAN NOT NULL DEFAULT TRUE,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" TIMESTAMPTZ,
  "sort_order" BIGINT NOT NULL DEFAULT 0
);
-- 兼容已由早期版本创建、但尚未包含排序字段的组织表。
ALTER TABLE "organization" ADD COLUMN IF NOT EXISTS "sort_order" BIGINT NOT NULL DEFAULT 0;
CREATE UNIQUE INDEX IF NOT EXISTS idx_organization_code_active ON "organization" ("code") WHERE "deleted_at" IS NULL;
CREATE INDEX IF NOT EXISTS idx_organization_parent_id ON "organization" ("parent_id");

CREATE TABLE IF NOT EXISTS "organization_user" (
  "organization_id" BIGINT NOT NULL REFERENCES "organization"("id") ON DELETE CASCADE,
  "user_id" BIGINT NOT NULL REFERENCES "user"("id") ON DELETE CASCADE,
  PRIMARY KEY ("organization_id", "user_id")
);
CREATE INDEX IF NOT EXISTS idx_organization_user_user_id ON "organization_user" ("user_id");

-- 默认根组织及历史用户的默认组织关联。
INSERT INTO "organization" ("name", "code", "manager", "status")
SELECT '默认组织', 'root', '', TRUE
WHERE NOT EXISTS (
  SELECT 1 FROM "organization" WHERE "code" = 'root' AND "deleted_at" IS NULL
);

INSERT INTO "organization_user" ("organization_id", "user_id")
SELECT root."id", users."id"
FROM "organization" AS root
CROSS JOIN "user" AS users
WHERE root."code" = 'root'
  AND root."deleted_at" IS NULL
  AND NOT EXISTS (
    SELECT 1
    FROM "organization_user" AS relation
    WHERE relation."organization_id" = root."id" AND relation."user_id" = users."id"
  );

COMMENT ON TABLE "role" IS '系统角色表';
COMMENT ON COLUMN "role"."id" IS '角色主键';
COMMENT ON COLUMN "role"."code" IS '角色编码，系统内唯一';
COMMENT ON COLUMN "role"."name" IS '角色名称';
COMMENT ON COLUMN "role"."description" IS '角色说明';
COMMENT ON COLUMN "role"."created_at" IS '创建时间';
COMMENT ON COLUMN "role"."updated_at" IS '更新时间';
COMMENT ON COLUMN "role"."deleted_at" IS '软删除时间';

COMMENT ON TABLE "user" IS '系统用户表';
COMMENT ON COLUMN "user"."id" IS '用户主键';
COMMENT ON COLUMN "user"."username" IS '登录用户名，系统内唯一';
COMMENT ON COLUMN "user"."password_hash" IS '密码哈希值';
COMMENT ON COLUMN "user"."nickname" IS '用户昵称';
COMMENT ON COLUMN "user"."status" IS '启用状态';
COMMENT ON COLUMN "user"."created_at" IS '创建时间';
COMMENT ON COLUMN "user"."updated_at" IS '更新时间';
COMMENT ON COLUMN "user"."deleted_at" IS '软删除时间';

COMMENT ON TABLE "user_role" IS '用户与角色多对多关联表';
COMMENT ON COLUMN "user_role"."user_id" IS '用户主键';
COMMENT ON COLUMN "user_role"."role_id" IS '角色主键';

COMMENT ON TABLE "organization" IS '组织架构表';
COMMENT ON COLUMN "organization"."id" IS '组织主键';
COMMENT ON COLUMN "organization"."parent_id" IS '上级组织主键，根组织为空';
COMMENT ON COLUMN "organization"."name" IS '组织名称';
COMMENT ON COLUMN "organization"."code" IS '组织编码，系统内唯一';
COMMENT ON COLUMN "organization"."manager" IS '组织负责人';
COMMENT ON COLUMN "organization"."status" IS '启用状态';
COMMENT ON COLUMN "organization"."created_at" IS '创建时间';
COMMENT ON COLUMN "organization"."updated_at" IS '更新时间';
COMMENT ON COLUMN "organization"."deleted_at" IS '软删除时间';
COMMENT ON COLUMN "organization"."sort_order" IS '同级组织排序值';

COMMENT ON TABLE "organization_user" IS '组织与用户多对多关联表';
COMMENT ON COLUMN "organization_user"."organization_id" IS '组织主键';
COMMENT ON COLUMN "organization_user"."user_id" IS '用户主键';

-- +goose Down
DROP TABLE IF EXISTS "organization_user";
DROP TABLE IF EXISTS "organization";
